contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount, uint256 extraDeposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        require(depositAmount > 0);

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        c.refund(); if (__ESBMC_reverted()) return;

        bool secondWithdrawSucceeded;
        c.withdraw(1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            secondWithdrawSucceeded = false;
        } else {
            secondWithdrawSucceeded = true;
        }

        assert(!secondWithdrawSucceeded);
    }

    receive() external payable {}
}

