// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 depositAmount, uint256 extraDeposit) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        vm.assume(depositAmount > 0);
        try c.deposit{value: depositAmount}() {} catch { return; }
        try c.refund() {} catch { return; }
        bool secondWithdrawSucceeded;
        try c.withdraw(1) {
            secondWithdrawSucceeded = true;
        } catch {
            secondWithdrawSucceeded = false;
        }
        assertTrue(!secondWithdrawSucceeded);
    }

    function testFuzz_run(uint256 depositAmount, uint256 extraDeposit) public {
        _run(depositAmount, extraDeposit);
    }

    receive() external payable {}
}
